<?php
require_once __DIR__.'/includes/permissions.php';
require_role('buyer');if(function_exists('require_verified_email'))require_verified_email();$page_title='Finalizar pedido';$u=user();$buyerId=(int)$u['buyer_id'];
$s=db()->prepare('SELECT ci.*,p.name,p.price,p.unit,p.stock,p.status,p.farmer_id,p.quantity_min FROM cart_items ci JOIN carts c ON c.id=ci.cart_id JOIN products p ON p.id=ci.product_id WHERE c.buyer_id=?');$s->execute([$buyerId]);$items=$s->fetchAll();if(!$items)redirect(base_path('carrinho.php'));$subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items));
// Métodos de pagamento: M-Pesa / e-Mola só ficam disponíveis quando ativados nas configurações.
$methods=['cash'=>['Dinheiro','bi-cash-coin',true],'mpesa'=>['M-Pesa','bi-phone',setting('payment_mpesa_enabled','0')==='1'],'emola'=>['e-Mola','bi-phone',setting('payment_emola_enabled','0')==='1'],'bank'=>['Transferência','bi-bank',true],'card'=>['Cartão','bi-credit-card',true]];
$zones=[];foreach(db()->query('SELECT province,district,fee,eta_days FROM delivery_zones WHERE is_active=1 ORDER BY province,district') as $z)$zones[mb_strtolower(trim($z['province']).'|'.trim($z['district']))]=['fee'=>(float)$z['fee'],'eta'=>(int)$z['eta_days'],'province'=>$z['province'],'district'=>$z['district']];
$old=['name'=>(string)($u['name']??''),'phone'=>(string)($u['phone']??''),'province'=>'Maputo','city'=>'Maputo','district'=>'','address'=>'','notes'=>'','payment_method'=>'cash','coupon_code'=>(string)($_SESSION['coupon_code']??'')];
if(is_post()){verify_csrf($_POST['csrf']??'');foreach($old as $k=>$v)$old[$k]=trim((string)($_POST[$k]??''));$old['coupon_code']=coupon_normalize($old['coupon_code']);$method=$old['payment_method'];$errors=[];
  foreach(['name','phone','province','city','district','address'] as $r)if($old[$r]==='')$errors[]='Preencha todos os dados de entrega.';
  if($old['phone']!==''&&!preg_match('/^\+?[0-9 ]{9,15}$/',$old['phone']))$errors[]='Indique um telefone válido.';
  if($old['province']!==''&&!in_array($old['province'],provinces(),true))$errors[]='Província inválida.';
  if(!isset($methods[$method]))$errors[]='Selecione um método de pagamento válido.';elseif(!$methods[$method][2])$errors[]=$methods[$method][0].' estará disponível brevemente. Escolha outro método.';
  if(mb_strlen($old['name'])>120||mb_strlen($old['city'])>80||mb_strlen($old['district'])>100||mb_strlen($old['address'])>255||mb_strlen($old['notes'])>1000)$errors[]='Algum campo excede o tamanho permitido.';
  if($errors)flash('danger',implode(' ',array_unique($errors)));
  else{try{$pdo=db();$pdo->beginTransaction();$locked=[];$subtotal=0;
    // Preços, stock e mínimos são lidos dentro da transação (linha bloqueada), não antes.
    foreach($items as $i){$lock=$pdo->prepare('SELECT id,name,price,unit,stock,status,quantity_min,farmer_id FROM products WHERE id=? FOR UPDATE');$lock->execute([$i['product_id']]);$cur=$lock->fetch();$q=(float)$i['quantity'];
      if(!$cur||$cur['status']!=='active')throw new RuntimeException('O produto '.$i['name'].' já não está disponível.');
      if($q<(float)$cur['quantity_min'])throw new RuntimeException('A quantidade mínima de '.$cur['name'].' é '.rtrim(rtrim(number_format((float)$cur['quantity_min'],2,'.',''),'0'),'.').' '.$cur['unit'].'.');
      if((float)$cur['stock']<$q)throw new RuntimeException('Stock insuficiente para '.$cur['name'].'.');
      $cur['quantity']=$q;$cur['line']=round((float)$cur['price']*$q,2);$subtotal+=$cur['line'];$locked[]=$cur;}
    // Cupão revalidado dentro da transação, com a linha do cupão bloqueada (used_count/max_uses consistentes).
    $coupon=null;$discount=0.0;if($old['coupon_code']!==''){$v=validate_coupon($old['coupon_code'],$subtotal,(int)$u['id'],$pdo,true);if(is_string($v))throw new RuntimeException('Cupão '.$old['coupon_code'].': '.$v);[$coupon,$discount]=$v;}
    $zone=delivery_zone($old['province'],$old['district']);$deliveryFee=(float)$zone['fee'];$deliveryEta=(int)$zone['eta_days'];$number='AG-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$total=round($subtotal-$discount+$deliveryFee,2);
    $s=$pdo->prepare('INSERT INTO orders (buyer_id,order_number,status,payment_status,subtotal,delivery_fee,discount,coupon_id,delivery_eta_days,total,delivery_name,delivery_phone,delivery_email,province,city,district,address,notes) VALUES(?,?,"pending","pending",?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$buyerId,$number,$subtotal,$deliveryFee,$discount,$coupon?(int)$coupon['id']:null,$deliveryEta,$total,$old['name'],$old['phone'],$u['email'],$old['province'],$old['city'],$old['district'],$old['address'],$old['notes']!==''?$old['notes']:null]);$oid=(int)$pdo->lastInsertId();assign_invoice_number($pdo,$oid);if($coupon)$pdo->prepare('UPDATE coupons SET used_count=used_count+1 WHERE id=?')->execute([$coupon['id']]);
    // Comissão da plataforma sobre o subtotal de cada item; o desconto do cupão é absorvido pela plataforma (farmer_amount não muda). A taxa de entrega é da plataforma.
    $rate=commission_percent();
    $farmerUsers=[];foreach($locked as $i){[,$comm,$net]=commission_split($i['line'],$rate);$pdo->prepare('INSERT INTO order_items(order_id,product_id,farmer_id,product_name,unit,unit_price,quantity,subtotal,commission_rate,commission_amount,farmer_amount,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,"pending")')->execute([$oid,$i['id'],$i['farmer_id'],$i['name'],$i['unit'],$i['price'],$i['quantity'],$i['line'],$rate,$comm,$net]);
      // MySQL avalia as atribuições da esquerda para a direita: o status usa o stock já atualizado.
      $pdo->prepare('UPDATE products SET stock=stock-?,sales_count=sales_count+?,status=IF(stock<=0,"out_of_stock",status) WHERE id=?')->execute([$i['quantity'],$i['quantity'],$i['id']]);$pdo->prepare('INSERT INTO inventory(product_id,quantity,movement_type,notes,created_by) VALUES(?,?,"sale",?,?)')->execute([$i['id'],-$i['quantity'],'Pedido '.$number,$u['id']]);
      $fs=$pdo->prepare('SELECT user_id FROM farmers WHERE id=?');$fs->execute([$i['farmer_id']]);if($fu=$fs->fetchColumn())$farmerUsers[(int)$fu][]=$i['name'];}
    foreach($farmerUsers as $fu=>$names)notify($fu,'Novo pedido recebido','O pedido '.$number.' inclui '.implode(', ',$names).'.');
    $pdo->prepare('INSERT INTO payments(order_id,amount,method,reference,status) VALUES(?,?,?,?,"pending")')->execute([$oid,$total,$method,'REF-'.$number]);$pdo->prepare('DELETE ci FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.buyer_id=?')->execute([$buyerId]);$pdo->commit();unset($_SESSION['coupon_code']);audit((int)$u['id'],'create','orders','Comprador criou o pedido '.$number.($coupon?' com o cupão '.$coupon['code'].' (−'.number_format($discount,2,'.','').')':''));redirect(base_path('pedido-confirmado.php?id='.$oid));
  }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('danger',$e instanceof RuntimeException?$e->getMessage():'Não foi possível criar o pedido.');}}}
$zone=delivery_zone($old['province'],$old['district']);$deliveryFee=(float)$zone['fee'];$deliveryEta=(int)$zone['eta_days'];$knownZone=isset($zones[mb_strtolower($old['province'].'|'.$old['district'])]);
$discount=0.0;$couponMsg='';if($old['coupon_code']!==''){$v=validate_coupon($old['coupon_code'],$subtotal,(int)$u['id']);if(is_string($v))$couponMsg=$v;else $discount=$v[1];}
include __DIR__.'/includes/header.php';
?><section class="container py-5"><div class="page-title-row"><div><span class="eyebrow">Passo 2 de 2</span><h1>Finalizar pedido</h1></div><div class="checkout-steps"><span class="done">1 Carrinho</span><span class="active">2 Confirmação</span></div></div><form method="post" id="checkoutForm"><div class="row g-4"><div class="col-lg-7"><div class="content-card mb-4"><h4><i class="bi bi-geo-alt me-2 text-primary"></i>Dados de entrega</h4><?=csrf_field()?><div class="row g-3 mt-1"><div class="col-md-6"><label class="form-label" for="ck-name">Nome completo</label><input id="ck-name" name="name" class="form-control" maxlength="120" value="<?=e($old['name'])?>" required></div><div class="col-md-6"><label class="form-label" for="ck-phone">Telefone</label><input id="ck-phone" name="phone" class="form-control" maxlength="20" placeholder="+258 8x xxx xxxx" value="<?=e($old['phone'])?>" required></div><div class="col-md-6"><label class="form-label" for="ck-province">Província</label><select id="ck-province" name="province" class="form-select" required><?php foreach(provinces() as $pv): ?><option value="<?=e($pv)?>" <?=$old['province']===$pv?'selected':''?>><?=e($pv)?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="ck-city">Cidade</label><input id="ck-city" name="city" class="form-control" maxlength="80" value="<?=e($old['city'])?>" required></div><div class="col-md-6"><label class="form-label" for="ck-district">Distrito</label><input id="ck-district" name="district" class="form-control" maxlength="100" list="ck-districts" value="<?=e($old['district'])?>" required autocomplete="off"><datalist id="ck-districts"><?php foreach($zones as $z): ?><option value="<?=e($z['district'])?>"><?=e($z['province'])?></option><?php endforeach; ?></datalist><div class="form-text">Zonas com taxa definida: <?=e(implode(', ',array_map(fn($z)=>$z['district'].' ('.$z['province'].')',$zones)))?>. Outras zonas: taxa a combinar.</div></div><div class="col-md-6"><label class="form-label" for="ck-address">Endereço</label><input id="ck-address" name="address" class="form-control" maxlength="255" value="<?=e($old['address'])?>" required></div><div class="col-12"><label class="form-label" for="ck-notes">Observações</label><textarea id="ck-notes" name="notes" class="form-control" rows="3" maxlength="1000"><?=e($old['notes'])?></textarea></div></div></div><div class="content-card"><h4><i class="bi bi-credit-card me-2 text-primary"></i>Método de pagamento</h4><p class="text-muted small">O pagamento fica registado como pendente até ser confirmado.</p><div class="payment-options"><?php foreach($methods as $key=>[$label,$icon,$enabled]): ?><label class="<?=$enabled?'':'opacity-50'?>"><input type="radio" name="payment_method" value="<?=e($key)?>" <?=$enabled?'':'disabled'?> <?=$enabled&&$old['payment_method']===$key?'checked':''?>><span><i class="bi <?=e($icon)?>"></i> <?=e($label)?><?php if(!$enabled): ?> <small class="text-muted">(brevemente)</small><?php endif; ?></span></label><?php endforeach; ?></div></div></div><div class="col-lg-5"><div class="summary-card sticky-lg-top" style="top:90px"><h4>Resumo</h4><?php foreach($items as $i): ?><div class="summary-product"><span><?=e($i['name'])?> <small>× <?=e($i['quantity'])?> <?=e($i['unit'])?></small></span><strong><?=money($i['price']*$i['quantity'])?></strong></div><?php endforeach; ?><hr><div class="summary-line"><span>Subtotal</span><strong><?=money($subtotal)?></strong></div><div class="summary-line"><span>Entrega <small class="text-muted d-block">Estimativa: <span id="ck-eta"><?=$deliveryEta?></span> dia(s)</small></span><strong id="ck-fee"><?=$knownZone?money($deliveryFee):'A combinar'?></strong></div><div class="summary-line text-success" id="ck-discount-row"<?=$discount>0?'':' hidden'?>><span>Desconto <small id="ck-coupon-label"><?=e($old['coupon_code'])?></small></span><strong id="ck-discount">−<?=money($discount)?></strong></div><div class="summary-line total mt-2"><span>Total</span><strong id="ck-total"><?=money($subtotal-$discount+$deliveryFee)?></strong></div><div class="mt-3"><label class="form-label small mb-1" for="ck-coupon"><i class="bi bi-ticket-perforated me-1"></i>Cupão de desconto</label><div class="input-group input-group-sm"><input id="ck-coupon" name="coupon_code" class="form-control text-uppercase" maxlength="30" value="<?=e($old['coupon_code'])?>" placeholder="Ex.: BEMVINDO10" autocomplete="off"><button type="button" class="btn btn-outline-primary" id="ck-coupon-apply">Aplicar</button><button type="button" class="btn btn-outline-secondary" id="ck-coupon-remove" title="Remover cupão" aria-label="Remover cupão"<?=$old['coupon_code']!==''?'':' hidden'?>><i class="bi bi-x-lg"></i></button></div><div class="form-text <?=$couponMsg?'text-danger':''?>" id="ck-coupon-msg"><?=e($couponMsg)?></div></div><button class="btn btn-primary btn-lg w-100 mt-4">Confirmar pedido <i class="bi bi-check2 ms-2"></i></button></div></div></div></form></section>
<script>
(function(){
  var zones=<?=json_encode((object)$zones,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,subtotal=<?=json_encode(round($subtotal,2))?>,discount=<?=json_encode(round($discount,2))?>;
  var pv=document.getElementById('ck-province'),ds=document.getElementById('ck-district');
  function fmt(v){return v.toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})+' MT';}
  var cc=document.getElementById('ck-coupon'),cm=document.getElementById('ck-coupon-msg'),cr=document.getElementById('ck-coupon-remove');
  async function coupon(action){cm.className='form-text';try{var r=await fetch(window.BASE_URL+'/api/cupao.php',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({csrf:window.CSRF,action:action,code:cc.value})});var d={};try{d=await r.json();}catch(e){}if(!r.ok||!d.success)throw new Error(d.message||'Ocorreu um erro.');
    discount=action==='apply'?d.discount:0;if(action==='remove')cc.value='';else cc.value=d.code;cm.textContent=d.message;cm.classList.add('text-success');}catch(e){discount=0;cm.textContent=e.message;cm.classList.add('text-danger');}
    document.getElementById('ck-discount-row').hidden=discount<=0;document.getElementById('ck-discount').textContent='\u2212'+fmt(discount);document.getElementById('ck-coupon-label').textContent=cc.value;cr.hidden=cc.value==='';update();}
  document.getElementById('ck-coupon-apply').addEventListener('click',function(){coupon('apply');});cr.addEventListener('click',function(){coupon('remove');});cc.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();coupon('apply');}});
  function update(){var z=zones[(pv.value.trim()+'|'+ds.value.trim()).toLowerCase()];var fee=z?z.fee:0;
    document.getElementById('ck-fee').textContent=z?fmt(fee):'A combinar';document.getElementById('ck-eta').textContent=z?z.eta:3;document.getElementById('ck-total').textContent=fmt(subtotal-discount+fee);}
  pv.addEventListener('change',update);ds.addEventListener('input',update);ds.addEventListener('change',update);
})();
</script><?php include __DIR__.'/includes/footer.php'; ?>
